CREATE DATABASE IF NOT EXISTS bgfc_inventory CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bgfc_inventory;
CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY, role_name VARCHAR(50) UNIQUE NOT NULL, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, username VARCHAR(100) UNIQUE NOT NULL, email VARCHAR(150), password VARCHAR(255) NOT NULL, role ENUM('ADMINISTRATOR','INVENTORY_OFFICER','STAFF') NOT NULL, status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, category_code VARCHAR(30) UNIQUE NOT NULL, category_name VARCHAR(100) NOT NULL, description VARCHAR(255), is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS suppliers (id INT AUTO_INCREMENT PRIMARY KEY, supplier_code VARCHAR(50) UNIQUE NOT NULL, supplier_name VARCHAR(150) NOT NULL, contact_person VARCHAR(150), contact_number VARCHAR(50), email VARCHAR(150), address TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, department_code VARCHAR(50) UNIQUE NOT NULL, department_name VARCHAR(150) NOT NULL, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS items (id INT AUTO_INCREMENT PRIMARY KEY, item_code VARCHAR(50) UNIQUE NOT NULL, item_name VARCHAR(150) NOT NULL, category_id INT, description TEXT, unit VARCHAR(50) NOT NULL, quantity INT NOT NULL DEFAULT 0, reorder_level INT NOT NULL DEFAULT 10, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT chk_item_quantity CHECK(quantity>=0), CONSTRAINT chk_reorder CHECK(reorder_level>=0), FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_transactions (id BIGINT AUTO_INCREMENT PRIMARY KEY, item_id INT NOT NULL, transaction_type ENUM('STOCK_IN','STOCK_OUT','ADJUSTMENT') NOT NULL, quantity INT NOT NULL, supplier_id INT NULL, department_id INT NULL, reference_no VARCHAR(100), purpose VARCHAR(255), remarks TEXT, user_id INT, transaction_date DATETIME DEFAULT CURRENT_TIMESTAMP, system_quantity INT NULL, actual_quantity INT NULL, adjustment_reason VARCHAR(100) NULL, FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_transaction_date(transaction_date), INDEX idx_transaction_item(item_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT, action VARCHAR(100), module VARCHAR(100), description TEXT, ip_address VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_audit_created(created_at)) ENGINE=InnoDB;
